const STANDARD_B64: string = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const REVERSED_B64: string = STANDARD_B64.split('').reverse().join('');

function hexEncode(buf: Buffer): string {
  return Array.from(buf).map((b: number) => b.toString(16).padStart(2, '0')).join('');
}

function bitGroups(buf: Buffer): string[] {
  const bits: string = Array.from(buf).map((b: number) => b.toString(2).padStart(8, '0')).join('');
  const groups: string[] = [];
  for (let i = 0; i < bits.length; i += 6) {
    groups.push(bits.slice(i, i + 6).padEnd(6, '0'));
  }
  return groups;
}

