function scheduleJobs(jobs: Job[], tolerance: number = 0): number {
  if (jobs.length === 0) return 0;

  // Sort jobs by end time
  jobs.sort((a, b) => a.end - b.end);

  // Precompute the latest non-overlapping job for each job
  const n = jobs.length;
  const prev: number[] = new Array(n).fill(-1);

  for (let i = 1; i < n; i++) {
    for (let j = i - 1; j >= 0; j--) {
      if (jobs[j].end + tolerance <= jobs[i].start) {
        prev[i] = j;
        break;
      }
    }
  }

  // Dynamic programming to find maximum weight
  const dp: number[] = new Array(n).fill(0);
  dp[0] = jobs[0].weight;

  for (let i = 1; i < n; i++) {
    const include = jobs[i].weight + (prev[i] !== -1 ? dp[prev[i]] : 0);
    const exclude = dp[i - 1];
    dp[i] = Math.max(include, exclude);
  }

