const STANDARD_B85: string = Array.from({ length: 85 }, (_, i) => String.fromCharCode(33 + i)).join('');
const REVERSED_B85: string = STANDARD_B85.split('').reverse().join('');

function leadingZeroBytes(data: Buffer): number {
  let count = 0;
  for (const b of data) {
    if (b !== 0) break;
    count++;
  }
  return count;
}

