// Template renderer: replaces %{key} with values from a context object.
// RULES:
// 1. Supports nested: %{a%{b}} -- inner resolved first, then outer
// 2. Escape: %%{ is NOT replaced (literal '%{' in output)
// 3. Unresolved keys stay as-is: %{unknown} => '%{unknown}'
// 4. Pipe filters: %{key|upper} applies uppercase, %{key|lower} applies lowercase
//
// render('Hello %{name}', {name: 'World'}) => 'Hello World'
// render('%%{name}', {name: 'X'}) => '%{name}'
// render('%{name|upper}', {name: 'hi'}) => 'HI'

// Helper: find matching close brace, respecting nested %{...}
function findCloseBrace(s: string, start: number): number {
  let d = 1, j = start;
  while (j < s.length && d > 0) {
    if (s[j] === '%' && s[j+1] === '{') { d++; j += 2; }
    else { if (s[j] === '}') d--; j++; }
  }
  return d === 0 ? j : -1;
}

