function isBalancedParens(text: string): boolean {
  let count = 0;
  for (const ch of text) {
    if (ch === '(') count++;
    else if (ch === ')') count--;
    if (count < 0) return false;
  }
  return count === 0;
}

function isBalancedBrackets(text: string): boolean {
  const stack: string[] = [];
  const pairs: Record<string, string> = {'(': ')', '[': ']', '{': '}'};
  for (const ch of text) {
    if (ch in pairs) stack.push(pairs[ch]);
    else if (Object.values(pairs).includes(ch)) {
      if (!stack.length || stack[stack.length - 1] !== ch) return false;
      stack.pop();
    }
  }
  return stack.length === 0;
}

