// Tokenize a simple expression language into typed tokens.
// Token types: 'num', 'str', 'op', 'ident', 'paren'
// Numbers: integer sequences (e.g. '42', '0')
// Strings: double-quoted with backslash escapes (\" and \\)
// Operators: +, -, *, /, ==, !=, >=, <=, >, <
// Identifiers: [a-zA-Z_][a-zA-Z0-9_]*
// Parens: ( and )
// Whitespace is skipped.
// CRITICAL: Multi-char operators (==, !=, >=, <=) must be parsed as ONE token.
//
// tokenize('x + 42') => [{type:'ident',val:'x'},{type:'op',val:'+'},{type:'num',val:'42'}]

interface Token { type: string; val: string; }

