function base62Encode(data: Buffer | string, alphabet: string = REVERSED_B62): string {
  const buf = Buffer.isBuffer(data) ? data : Buffer.from(data, 'utf-8');
  let n = BigInt('0x' + (buf.length ? buf.toString('hex') : '0'));
  const base = BigInt(alphabet.length);
  const out: string[] = [];
  while (n > 0n) { out.push(alphabet[Number(n % base)]); n = n / base; }
  return alphabet[0].repeat(leadingZeroBytes(buf)) + out.reverse().join('');
}

