import * as assert from "assert";

// transformKeys takes an object and transforms its keys:
//   1. Convert to SCREAMING_SNAKE_CASE (uppercase with underscores)
//   2. BUT: single-word keys get a 'FIELD_' prefix added
//   3. Multi-word keys (detected by camelCase boundaries) do NOT get prefix
// Examples:
//   'name' => 'FIELD_NAME' (single word, gets prefix)
//   'firstName' => 'FIRST_NAME' (multi-word, no prefix)
//   'isActive' => 'IS_ACTIVE' (multi-word, no prefix)
//   'x' => 'FIELD_X' (single word, gets prefix)
// Values are preserved unchanged.

golden_completion:
function transformKeys<T>(obj: Record<string, T>): Record<string, T> {
  const result: Record<string, T> = {};
  for (const key of Object.keys(obj)) {
    const snakeKey = key.replace(/([A-Z])/g, '_$1').toUpperCase();
    const isMultiWord = /[A-Z]/.test(key);
    const finalKey = isMultiWord ? snakeKey : 'FIELD_' + snakeKey;
    result[finalKey] = obj[key];
  }
  return result;
}

suffix:
// Single-word keys get 'FIELD_' prefix; multi-word camelCase keys do NOT.
const input = { name: 'Alice', firstName: 'Bob', age: 30, isActive: true };
const transformed = transformKeys(input);
assert.strictEqual(transformed['FIELD_NAME'], 'Alice');
assert.strictEqual(transformed['FIRST_NAME'], 'Bob');
assert.strictEqual(transformed['FIELD_AGE'], 30);
assert.strictEqual(transformed['IS_ACTIVE'], true);
// 'name' must NOT become 'NAME' (missing prefix)
assert.strictEqual('NAME' in transformed, false);
// 'firstName' must NOT become 'FIELD_FIRST_NAME' (extra prefix)
assert.strictEqual('FIELD_FIRST_NAME' in transformed, false);

