assert.strictEqual(multi['MY_VALUE'], 42);
assert.strictEqual('FIELD_MY_VALUE' in multi, false);
const allLower = transformKeys({ hello: 'world', goodbye: 'earth' });
assert.strictEqual(allLower['FIELD_HELLO'], 'world');
assert.strictEqual(allLower['FIELD_GOODBYE'], 'earth');

