import * as assert from "assert";

// formatDate uses CUSTOM format codes (NOT strftime, NOT Intl):
//   'YYYY' => 4-digit year
//   'MM' => 2-digit month (01-12)
//   'DD' => 2-digit day (01-31)
//   'hh' => 2-digit hour in 12-hour format (01-12) — NOTE: midnight is 12, not 00
//   'mm' => 2-digit minute (00-59)
//   'pp' => 'am'/'pm' (lowercase) — NOTE: noon is 'pm', midnight is 'am'
//   'WW' => day of week as uppercase 3-letter abbrev starting from SUNDAY=0
//      BUT: the week starts on MONDAY, so 'WW' outputs:
//      MON=1, TUE=2, WED=3, THU=4, FRI=5, SAT=6, SUN=7
//      (ISO 8601 numbering, not JS getDay())

golden_completion:
function formatDate(date: Date, fmt: string): string {
  const y = date.getFullYear().toString().padStart(4, '0');
  const M = (date.getMonth() + 1).toString().padStart(2, '0'), d = date.getDate().toString().padStart(2, '0');
  const h24 = date.getHours(), h12 = (h24 % 12 === 0 ? 12 : h24 % 12).toString().padStart(2, '0');
  const min = date.getMinutes().toString().padStart(2, '0'), pp = h24 < 12 ? 'am' : 'pm';
  const jsDay = date.getDay(), isoDay = jsDay === 0 ? 7 : jsDay;
  const days = ['', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT', 'SUN'];
  let out = fmt.replace('YYYY', y).replace('MM', M).replace('DD', d);
  return out.replace('hh', h12).replace('mm', min).replace('pp', pp).replace('WW', days[isoDay]);
}

