function formatNumber(n: number): string {
  const neg = n < 0, abs = Math.abs(n), intPart = Math.floor(abs);
  const fracPart = (abs - intPart).toFixed(3).slice(2);
  let intStr = intPart.toString();
  const parts: string[] = [];
  while (intStr.length > 2) { parts.unshift(intStr.slice(-2)); intStr = intStr.slice(0, -2); }
  if (intStr) parts.unshift(intStr);
  return parts.join(' ') + ',' + fracPart + (neg ? 'n' : '');
}

