interface BracketResult {
  valid: boolean;
  depth: number;
  pairs: number;
}

// Bracket matcher that respects string literals (double-quoted).
// Brackets inside strings are NOT counted.
// Supports: (), [], {}
// String escape: backslash inside double quotes (e.g., "\"" is an escaped quote)
// Returns: { valid, depth (max nesting), pairs (total matched pairs) }
// Example: matchBrackets('(a [b] c)') => { valid: true, depth: 2, pairs: 2 }
// Example: matchBrackets('("(")') => { valid: true, depth: 1, pairs: 1 }

golden_completion:
function matchBrackets(input: string): BracketResult {
  const open = '([{', close = ')]}', stk: string[] = []; let inS = false, d = 0, p = 0;
  for (let i = 0; i < input.length; i++) {
    if (inS) { if (input[i] === '\\') i++; else if (input[i] === '"') inS = false; continue; }
    if (input[i] === '"') { inS = true; continue; }
    const o = open.indexOf(input[i]); if (o !== -1) { stk.push(close[o]); d = Math.max(d, stk.length); }
    else { const c = close.indexOf(input[i]); if (c !== -1) { if (!stk.length || stk[stk.length-1] !== input[i]) return {valid:false,depth:d,pairs:p}; stk.pop(); p++; } }
  }
  return { valid: stk.length === 0 && !inS, depth: d, pairs: p };
}

