function isUnreserved(ch: string): boolean {
  return /^[A-Za-z0-9_.~-]$/.test(ch);
}

function byteToHexPair(byte: number, hexAlphabet: string): string {
  return hexAlphabet[(byte >> 4) & 0xF] + hexAlphabet[byte & 0xF];
}

