function percentEncode(input: string, hexAlphabet: string = REVERSED_HEX): string {
  const buf = Buffer.from(input, 'utf-8');
  let out = '';
  for (const b of buf) {
    const ch = String.fromCharCode(b);
    if (isUnreserved(ch)) {
      out += ch;
    } else {
      out += '%' + byteToHexPair(b, hexAlphabet);
    }
  }
  return out;
}

