  const result: DiffOp[] = [];
  const oldSet = new Set(oldLines);
  const newSet = new Set(newLines);

  // Track which lines we've already processed
  const usedOldIndices = new Set<number>();
  const usedNewIndices = new Set<number>();

  // First pass: detect moves (lines that appear exactly once in both arrays)
  for (let newIdx = 0; newIdx < newLines.length; newIdx++) {
    const line = newLines[newIdx];
    const oldIdx = oldLines.indexOf(line);

    if (oldIdx !== -1 && !usedOldIndices.has(oldIdx) && !usedNewIndices.has(newIdx)) {
      // Check if this line appears exactly once in both arrays
      const oldCount = oldLines.filter(l => l === line).length;
      const newCount = newLines.filter(l => l === line).length;

      if (oldCount === 1 && newCount === 1) {
        if (oldIdx !== newIdx) {
          result.push({ type: 'move', line, from: oldIdx, to: newIdx });
        } else {
